<div class="nc-table-wrap"><table class="nc-table"><thead><tr><th>#</th><th>{{ __('Product') }}</th><th>{{ __('Reviewer') }}</th><th>{{ __('Rating') }}</th><th>{{ __('Status') }}</th><th>{{ __('Created') }}</th><th>{{ __('Actions') }}</th></tr></thead><tbody>
